<div class="form-grid"><label>Title<input name="title" value="<?=e($item['title']??'')?>" required></label><label>Slug<input name="slug" value="<?=e($item['slug']??'')?>" placeholder="generated-from-title"></label><label>Status<select name="status"><?php foreach(['draft','published','archived'] as $s):?><option <?=($item['status']??'draft')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><label>Sort order<input type="number" name="sort_order" value="<?=e((string)($item['sort_order']??0))?>"></label></div><label>Summary<textarea name="summary" rows="2"><?=e($item['summary']??'')?></textarea></label><label>Body<textarea name="body" rows="5"><?=e($item['body']??'')?></textarea></label><div class="form-grid"><label>SEO title<input name="meta_title" value="<?=e($item['meta_title']??'')?>"></label><label>SEO description<input name="meta_description" value="<?=e($item['meta_description']??'')?>"></label></div><label class="check"><input type="checkbox" name="is_featured" value="1" <?=($item['is_featured']??0)?'checked':''?>> Featured content</label>
